+
+    button:focus-visible {
+      outline: 3px solid rgba(88, 166, 255, 0.55);
+      outline-offset: 3px;
+    }
+
+    button:active {
+      transform: translateY(0);
+    }
+
+    .success-message {
+      display: none;
+      margin: 18px 0 0;
+      padding: 13px 15px;
+      border: 1px solid rgba(63, 185, 80, 0.5);
+      border-radius: 14px;
+      background: rgba(46, 160, 67, 0.14);
+      color: #7ee787;
+      font-weight: 700;
+    }
+
+    .success-message.visible {
+      display: block;
+    }
+
