+</head>
+<body>
+  <main>
+    <section class="support-card" aria-labelledby="support-title">
+      <h1 id="support-title">Contact support</h1>
+      <p class="intro">Tell us how to reach you and our support team will follow up shortly.</p>
+
+      <form id="support-form" novalidate>
+        <div class="form-field">
+          <label for="full-name">Full name</label>
+          <input
+            type="text"
+            id="full-name"
+            name="fullName"
+            autocomplete="name"
+            placeholder="Jane Doe"
+            required
+            aria-describedby="full-name-error"
+          >
+          <p class="error-message" id="full-name-error">Please enter your full name.</p>
+        </div>
+
+        <div class="form-field">
+          <label for="email-address">Email address</label>
+          <input
+            type="email"
+            id="email-address"
+            name="emailAddress"
+            autocomplete="email"
+            placeholder="jane@example.com"
+            required
+            aria-describedby="email-address-error"
+          >
+          <p class="error-message" id="email-address-error">Please enter a valid email address.</p>
+        </div>
+
+        <div class="form-field">
+          <label for="phone-number">Phone number <span aria-hidden="true">(optional)</span></label>
+          <input
+            type="tel"
+            id="phone-number"
