 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Support Contact Form</title>
   <style>
     :root {
       color-scheme: dark;
       --bg: #0d1117;
       --panel: #161b22;
       --panel-border: #30363d;
       --text: #f0f6fc;
       --muted: #8b949e;
       --accent: #58a6ff;
       --accent-strong: #1f6feb;
       --danger: #ff7b72;
       --input: #0d1117;
       --shadow: rgba(1, 4, 9, 0.45);
     }

     * {
       box-sizing: border-box;
     }

     body {
       min-height: 100vh;
       margin: 0;
       display: grid;
       place-items: center;
       padding: 32px 16px;
       background:
         radial-gradient(circle at top left, rgba(88, 166, 255, 0.16), transparent 32rem),
         linear-gradient(135deg, #070a10 0%, var(--bg) 55%, #101624 100%);
       color: var(--text);
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       line-height: 1.5;
     }

     main {
       width: min(100%, 520px);
     }

     .support-card {
       padding: 34px;
       border: 1px solid var(--panel-border);
       border-radius: 24px;
       background: rgba(22, 27, 34, 0.88);
       box-shadow: 0 24px 80px var(--shadow);
       backdrop-filter: blur(14px);
     }

     h1 {
       margin: 0 0 10px;
       font-size: clamp(2rem, 6vw, 3rem);
       line-height: 1.05;
       letter-spacing: -0.04em;
     }

     .intro {
       margin: 0 0 28px;
       color: var(--muted);
       font-size: 1rem;
     }

     .form-field {
       margin-bottom: 20px;
     }

     label {
       display: block;
       margin-bottom: 8px;
       color: #c9d1d9;
       font-weight: 700;
       font-size: 0.95rem;
     }

     input {
       width: 100%;
       border: 1px solid var(--panel-border);
       border-radius: 14px;
       padding: 14px 16px;
       background: var(--input);
       color: var(--text);
       font: inherit;
       outline: none;
       transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
     }

     input::placeholder {
       color: #6e7681;
     }

     input:focus {
       border-color: var(--accent);
       box-shadow: 0 0 0 4px rgba(88, 166, 255, 0.18);
       background: #101620;
     }

     input[aria-invalid="true"] {
       border-color: var(--danger);
     }

     .helper-text {
       margin: 7px 0 0;
       color: var(--muted);
       font-size: 0.875rem;
     }

     .error-message {
       display: none;
       margin: 7px 0 0;
       color: var(--danger);
       font-size: 0.875rem;
     }

     .error-message.visible {
       display: block;
     }

     button {
       width: 100%;
       margin-top: 6px;
       border: 0;
       border-radius: 14px;
       padding: 15px 18px;
       background: linear-gradient(135deg, var(--accent), var(--accent-strong));
       color: #ffffff;
       font: inherit;
       font-weight: 800;
       cursor: pointer;
       box-shadow: 0 12px 30px rgba(31, 111, 235, 0.28);
       transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease;
     }

     button:hover {
       transform: translateY(-1px);
       box-shadow: 0 16px 34px rgba(31, 111, 235, 0.36);
       filter: brightness(1.06);
     }

     button:focus-visible {
       outline: 3px solid rgba(88, 166, 255, 0.55);
       outline-offset: 3px;
     }

     button:active {
       transform: translateY(0);
     }

     .success-message {
       display: none;
       margin: 18px 0 0;
       padding: 13px 15px;
       border: 1px solid rgba(63, 185, 80, 0.5);
       border-radius: 14px;
       background: rgba(46, 160, 67, 0.14);
       color: #7ee787;
       font-weight: 700;
     }

     .success-message.visible {
       display: block;
     }

     @media (max-width: 520px) {
       .support-card {
         padding: 26px 20px;
         border-radius: 20px;
       }
     }
   </style>
 </head>
 <body>
   <main>
     <section class="support-card" aria-labelledby="support-title">
       <h1 id="support-title">Contact support</h1>
       <p class="intro">Tell us how to reach you and our support team will follow up shortly.</p>

       <form id="support-form" novalidate>
         <div class="form-field">
           <label for="full-name">Full name</label>
           <input
             type="text"
             id="full-name"
             name="fullName"
             autocomplete="name"
             placeholder="Jane Doe"
             required
             aria-describedby="full-name-error"
           >
           <p class="error-message" id="full-name-error">Please enter your full name.</p>
         </div>

         <div class="form-field">
           <label for="email-address">Email address</label>
           <input
             type="email"
             id="email-address"
             name="emailAddress"
             autocomplete="email"
             placeholder="jane@example.com"
             required
             aria-describedby="email-address-error"
           >
           <p class="error-message" id="email-address-error">Please enter a valid email address.</p>
         </div>

         <div class="form-field">
           <label for="phone-number">Phone number <span aria-hidden="true">(optional)</span></label>
           <input
             type="tel"
             id="phone-number"
             name="phoneNumber"
             autocomplete="tel"
             placeholder="+1 555 123 4567"
             aria-describedby="phone-number-help"
             pattern="^[+]?[0-9\s().-]{7,20}$"
           >
           <p class="helper-text" id="phone-number-help">Use an international format when possible, for example +1 555 123 4567.</p>
         </div>

         <button type="submit">Submit request</button>
         <p class="success-message" id="success-message" role="status">Thanks! Your support request is ready to send.</p>
       </form>
     </section>
   </main>

   <script>
     const form = document.querySelector("#support-form");
     const successMessage = document.querySelector("#success-message");
     const requiredFields = [
       {
         input: document.querySelector("#full-name"),
         error: document.querySelector("#full-name-error"),
         isValid: (value) => value.trim().length > 0
       },
       {
         input: document.querySelector("#email-address"),
         error: document.querySelector("#email-address-error"),
         isValid: (value) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())
       }
     ];

     function setFieldState(field, shouldValidate) {
       const isValid = field.isValid(field.input.value);

       field.input.setAttribute("aria-invalid", shouldValidate && !isValid ? "true" : "false");
       field.error.classList.toggle("visible", shouldValidate && !isValid);

       return isValid;
     }

     requiredFields.forEach((field) => {
       field.input.addEventListener("input", () => {
         if (field.input.dataset.touched === "true") {
           setFieldState(field, true);
         }
       });

       field.input.addEventListener("blur", () => {
         field.input.dataset.touched = "true";
         setFieldState(field, true);
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();
       successMessage.classList.remove("visible");

       const isFormValid = requiredFields.every((field) => {
         field.input.dataset.touched = "true";
         return setFieldState(field, true);
       });

       if (isFormValid) {
         successMessage.classList.add("visible");
         form.reset();
         requiredFields.forEach((field) => {
           field.input.dataset.touched = "false";
           setFieldState(field, false);
         });
       }
     });
   </script>
 </body>
 </html>

